export type Transformer<T = any, R = any> = (value: T, ...args: any[]) => R | Promise<R>;
export const identity: Transformer;
export const compose: (...transformers: Transformer[]) => Transformer;
export const pipe: typeof compose;
export const trimString: Transformer<string>;
export const lowercase: Transformer<string>;
export const uppercase: Transformer<string>;
export const normalizeEmail: Transformer<string>;
export const normalizeWhitespace: Transformer<string>;
export const slugify: Transformer<string>;
export const toNumber: (value: any, options?: { strict?: boolean }) => any;
export const toBoolean: (value: any, options?: { strict?: boolean }) => any;
export const toInteger: (value: any, options?: { strict?: boolean }) => any;
export const parseJSON: (value: any, options?: { strict?: boolean }) => any;
export const pick: (keys: string[]) => Transformer;
export const omit: (keys: string[]) => Transformer;
export const renameFields: (mapping: Record<string, string>) => Transformer;
export const mapFields: (mapping: Record<string, Transformer>) => Transformer;
export const trimStrings: (options?: { fields?: string[]; recursive?: boolean }) => Transformer;
export const removeEmpty: (options?: Record<string, boolean>) => Transformer;
export const setDefaults: (defaults: Record<string, any>) => Transformer;
export const mapArray: (transformer: Transformer) => Transformer;
export const updatePath: (path: string, transformer: Transformer) => Transformer;
